import sys
from collections import deque

def main():
    d = sys.stdin.read().split()
    n, m, k = int(d[0]), int(d[1]), int(d[2])
    g = [[int(d[3 + i * m + j]) for j in range(m)] for i in range(n)]
    cells = n * m
    adj = [[] for _ in range(cells)]
    for i in range(n):
        for j in range(m):
            if g[i][j] == 0:
                for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = i + di, j + dj
                    if 0 <= a < n and 0 <= b < m and g[a][b] == 0:
                        adj[i * m + j].append(a * m + b)
    INF = 10 ** 9
    dist = [INF] * cells
    dist[0] = 0
    dq = deque([0])
    while dq:
        u = dq.popleft()
        for v in adj[u]:
            if dist[v] == INF:
                dist[v] = dist[u] + 1
                dq.append(v)
    best = 1
    SH = 7
    cur = {(1 << 0) << SH | 0}
    for step in range(k):
        rem = k - step - 1
        nxt = set()
        for key in cur:
            pos = key & 127
            mask = key >> SH
            for q in adj[pos]:
                if dist[q] <= rem:
                    nxt.add(((mask | (1 << q)) << SH) | q)
        cur = nxt
        for key in cur:
            if key & 127 == 0:
                c = bin(key >> SH).count('1')
                if c > best:
                    best = c
    print(best)

main()

